const original=[{name:'Identity',shape:'THE THREAD',title:'Who am I, beyond the labels?',text:'Student. Friend. Son. A person with plans.\n\nIt is easy to confuse who I am with what I achieve. Faith offers another starting point: a person has dignity before they earn a grade, win recognition, or prove their worth.\n\nIn this artwork, one continuous thread folds back on itself. It suggests that my relationships, values, and choices belong to one story—even when they seem to pull in different directions.',question:'If nobody could see my achievements, what would I still want them to know about me?',connection:'Christian theme: the dignity of the human person and being made in the image of God. Class connection to explore: Genesis 1:26–27. Add a personal experience and your class’s preferred translation.'},{name:'Doubt',shape:'THE OPEN CIRCLE',title:'Room for the unanswered.',text:'A question can be an act of attention.\n\nThis unfinished circle represents the space between wanting certainty and learning to live honestly with questions. I do not have to pretend that every part of faith is easy to understand.\n\nThe opening is intentional. It leaves room to listen, to learn, and to reconsider. A growing faith can include a willingness to ask difficult questions.',question:'What question am I willing to sit with instead of rushing to answer?',connection:'Christian theme: faith alongside uncertainty. Class connection to explore: Thomas’s questions in John 20:24–29. Reflect on how questioning and trust relate; explain your own interpretation.'},{name:'Service',shape:'THE RIPPLE',title:'Belief becomes a choice.',text:'An idea matters differently when it changes how I treat someone.\n\nThe ripple begins at one point and travels outward. It represents a simple act of care: listening without checking my phone, showing up when help is needed, or noticing someone who feels left out.\n\nService asks me to turn inward beliefs into outward action. The question becomes less about appearing good and more about being useful to another person.',question:'Who benefits from the person I am becoming?',connection:'Christian theme: love of neighbor expressed through action. Class connection to explore: the Good Samaritan, Luke 10:25–37. Replace this sample with a real moment of service and what it taught you.'},{name:'Hope',shape:'THE LIGHT',title:'Not finished. Still growing.',text:'Hope does not mean knowing how everything will work out.\n\nThe final form rises like a small flame. Its points never become perfectly still. It suggests that growth is ongoing, and that a mistake does not have to become my entire identity.\n\nI can take responsibility, begin again, and make a different next choice. This self-portrait ends with a direction, not a final answer.',question:'What is one choice I can make tomorrow that brings me closer to my values?',connection:'Christian themes: renewal, forgiveness, and hope. Class connection to explore: the return of the younger son in Luke 15:11–32. Connect the artwork to a lesson or passage studied in your course.'}];
let reflections=original.slice(0,3).map(x=>({...x}));try{let saved=JSON.parse(localStorage.getItem('becoming-reflections-v1'));if(Array.isArray(saved)&&saved.length>=3&&saved.every(x=>['name','shape','title','text','question','connection'].every(k=>typeof x[k]==='string')))reflections=saved.slice(0,3)}catch{}const $=s=>document.querySelector(s);let selected=0;const tabs=[...document.querySelectorAll('[data-theme]')];function selectTheme(n){selected=(n+reflections.length)%reflections.length;let r=reflections[selected];$('#chapterNo').textContent=`0${selected+1} / ${r.name.toUpperCase()}`;$('#chapterTitle').textContent=r.title;$('#chapterText').textContent=r.text;$('#chapterQuestion').textContent=r.question;$('#chapterConnection').textContent=r.connection;$('#fig').textContent='0'+(selected+1);$('#shapeName').textContent=r.shape;tabs.forEach((b,i)=>{b.setAttribute('aria-selected',String(i===selected));b.tabIndex=i===selected?0:-1});targetForm=selected}tabs.forEach((b,i)=>{b.onclick=()=>selectTheme(i);b.onkeydown=e=>{if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key)){e.preventDefault();selectTheme(selected+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1));tabs[selected].focus()}}});$('#seeArt').onclick=()=>{manualTheme=true;window.scrollTo({top:$('.hero').offsetTop+(selected/(reflections.length-1))*($('.hero').offsetHeight-innerHeight),behavior:reduced?'instant':'smooth'})};
const canvas=$('#sculpture'),ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced,angle=.45,tilt=-.24,zoom=1,drag=false,lastX=0,lastY=0,w=0,h=0,dpr=1,tick=0,targetForm=0,manualTheme=false;let lastScroll=0;const N=2400,points=[],targets=[[],[],[],[]];function rand(i){let v=Math.sin(i*127.1+311.7)*43758.5453;return v-Math.floor(v)}function center(t){return [(2+Math.cos(3*t))*.36*Math.cos(2*t),(2+Math.cos(3*t))*.36*Math.sin(2*t),Math.sin(3*t)*.36]};
